<script setup>
import { computed, ref } from 'vue'
import { Download, Search, RotateCcw, ArrowLeft, ArrowRight } from 'lucide-vue-next'
import { useAppStore } from '../stores/app'
import { money, localDate, statusNames } from '../utils/format'
import PaymentTable from '../components/PaymentTable.vue'
const store=useAppStore(), status=ref(''), employee=ref(''), from=ref(''), until=ref(''), page=ref(1)
const filtered=computed(()=>store.sortedPayments.filter(p=>(!status.value||p.status===status.value)&&(!employee.value||p.employeeId===employee.value)&&(!from.value||localDate(p.createdAt)>=from.value)&&(!until.value||localDate(p.createdAt)<=until.value)))
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10)))
const currentPage=computed(()=>Math.min(page.value,pages.value))
const visible=computed(()=>filtered.value.slice((currentPage.value-1)*10,currentPage.value*10))
function reset(){status.value='';employee.value='';from.value='';until.value='';page.value=1}
function download(){const safe = s => `"${String(s).replace(/"/g,'""').replace(/^[=+@-]/,"'")}"`;const csv='\uFEFF'+[['ID','Дата','Сотрудник','Сумма','Статус'],...filtered.value.map(p=>[p.id,new Date(p.createdAt).toLocaleString('ru-RU'),store.employeeName(p.employeeId),p.amount,statusNames[p.status]])].map(row=>row.map(safe).join(';')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='tipro-payments.csv';a.click();URL.revokeObjectURL(url);store.notify('История экспортирована в CSV')}
</script>
<template><div class="page-heading"><div><h1>{{ store.session?.role==='employee'?'Мои платежи':'Платежи ресторана' }}</h1><p>{{ store.session?.role==='employee'?'Здесь отображаются только ваши чаевые.':'Все платежи команды вашего ресторана.' }}</p></div><button class="btn btn-outline" @click="download" :disabled="!filtered.length"><Download :size="17"/>Экспорт CSV</button></div><section class="panel"><div class="filters"><label>Статус<select v-model="status" @change="page=1"><option value="">Все статусы</option><option value="success">Успешно</option><option value="declined">Отклонён</option><option value="cancelled">Отменён</option></select></label><label v-if="store.session?.role==='merchant'">Сотрудник<select v-model="employee" @change="page=1"><option value="">Вся команда</option><option v-for="e in store.employees" :value="e.id" :key="e.id">{{ e.name }}</option></select></label><label>С даты<input type="date" v-model="from" :max="until || undefined" @change="page=1"></label><label>По дату<input type="date" v-model="until" :min="from || undefined" @change="page=1"></label><button class="icon-btn" @click="reset" aria-label="Сбросить фильтры" title="Сбросить фильтры"><RotateCcw :size="18"/></button></div><div class="filter-summary"><span>Найдено платежей: <strong>{{ filtered.length }}</strong></span><span>Успешные чаевые: <strong>{{ money(filtered.filter(p=>p.status==='success').reduce((s,p)=>s+p.amount,0)) }}</strong></span></div><PaymentTable :payments="visible" :employee-name="store.employeeName"/><div class="pagination"><span>Страница {{ currentPage }} из {{ pages }}</span><div><button class="icon-btn" :disabled="currentPage===1" @click="page=currentPage-1" aria-label="Предыдущая страница"><ArrowLeft :size="17"/></button><button class="icon-btn" :disabled="currentPage===pages" @click="page=currentPage+1" aria-label="Следующая страница"><ArrowRight :size="17"/></button></div></div></section></template>
